export function orchardNextStep(state,key){const p=state.cossenne?.expeditions?.[key],name=key==='grove'?'Old Pilgrim Grove':'Sunken Shrine',guard=key==='grove'?'TRN-C05-005':'TRN-C05-007';if(p?.claimed)return name+': complete. The decision and rewards are recorded.';if(p?.choice)return name+': return to the entrance attendant to collect your reward.';if(!p?.accepted)return name+': '+(key==='grove'?'take the northern turn at Resin Bend and speak to the Grove attendant.':'take the northern landing at Ash Slope with Alice’s river craft; speak to the Archive attendant.');if(!p.records.includes(0))return name+': read the first stretch’s Old site record, then use the eastern passage.';if(!p.records.includes(1))return name+': continue east and read the middle stretch’s Repair instructions.';if(!p.solved)return name+': set the three middle-stretch wheels, left to right, to '+(key==='grove'?'2 · 1 · 3. A living Grass partner can assist.':'3 · 2 · 1. A living Water partner can assist.');if(!p.records.includes(2))return name+': continue east to the final stretch and read the Final register.';if(!state.defeatedTrainers?.includes(guard))return name+': challenge '+(key==='grove'?'Zaynab at the two altars.':'Asma at the rooted archive.');return name+': use the final decision marker, review both consequences and rewards, then confirm your choice.';}
